package org.spazio17.muralis;

/**
 * The colour schemes a person can choose on This panel: three seed colours, each Material 3
 * from its seed, dark and light, fifteen colours: the thirteen of KioskTheme's
 * constructor, then on-primary and surface-container-lowest.
 * GENERATED by scripts/gen-palettes.py with Google's material-color-utilities; edit the
 * script, not this file. Pure, for the host tests.
 */
final class Palettes {
    private Palettes() {
    }

    /** The colours offered, in the order the picker lists them; the first is the default. */
    static final String[] COLOURS = {"purple", "blue", "orange"};
    /** A scheme's fifteen colours, dark or light, or null for a colour not offered. */
    static String[] colours(String colour, boolean dark) {
        switch (colour + (dark ? "-dark" : "-light")) {
            case "purple-dark":
                return new String[] {"#16121b", "#100c16", "#2d2833", "#38333e", "#968d9e", "#e9dfee", "#cdc3d4", "#d8baff", "#d1bfe7", "#8ee88a", "#ffdf8f", "#ffb4a9", "#eedcff", "#43008a", "#100c16"};
            case "purple-light":
                return new String[] {"#fff7ff", "#ffffff", "#eee5f3", "#e9dfee", "#7c7484", "#1e1a24", "#4b4453", "#7e00f9", "#67587b", "#227212", "#905600", "#ba1b1b", "#221534", "#ffffff", "#ffffff"};
            case "blue-dark":
                return new String[] {"#0f131c", "#0a0e17", "#262a33", "#343538", "#8b909f", "#dfe2ef", "#c1c6d6", "#abc7ff", "#b8c7ea", "#8ee88a", "#ffdf8f", "#ffb4a9", "#d6e2ff", "#002e6a", "#0a0e17"};
            case "blue-light":
                return new String[] {"#f9f9ff", "#ffffff", "#e5e8f5", "#dfe2ef", "#727785", "#171c25", "#424754", "#005ac1", "#505f7d", "#227212", "#905600", "#ba1b1b", "#0b1b36", "#ffffff", "#ffffff"};
            case "orange-dark":
                return new String[] {"#1d1109", "#170c05", "#36271d", "#413127", "#a58c7c", "#f8decf", "#dec1b0", "#ffb683", "#f1bb98", "#8ee88a", "#ffdf8f", "#ffb4a9", "#ffdbc4", "#512400", "#170c05"};
            case "orange-light":
                return new String[] {"#fff8f4", "#ffffff", "#fde3d4", "#f8decf", "#8a7264", "#261910", "#574336", "#974900", "#7e5539", "#227212", "#905600", "#ba1b1b", "#301401", "#ffffff", "#ffffff"};
            default:
                return null;
        }
    }
}
